//! The embedded content table, generated by `build.rs` from `content/`.

include!(concat!(env!("OUT_DIR"), "/content_files.rs"));

/// Bytes of one embedded file; `path` is relative to `content/`.
pub fn embedded(path: &str) -> Option<&'static [u8]> {
    EMBEDDED.iter().find(|(p, _)| *p == path).map(|(_, b)| *b)
}

/// FNV-1a 64 over the raw bytes. The hash every content file is known by.
pub fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

/// 16 lowercase hex digits.
pub fn hex(u: u64) -> String {
    format!("{u:016x}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fnv_known_values() {
        assert_eq!(fnv1a64(b""), 0xcbf29ce484222325);
        assert_eq!(fnv1a64(b"a"), 0xaf63dc4c8601ec8c);
    }

    /// Shared with the editor (`src/content/hash.test.ts`): the same UTF-8
    /// text must hash the same on both sides.
    #[test]
    fn shared_vector_matches_the_editor() {
        const SHARED_TEXT: &str = "{\n  \"v\": 1,\n  \"values\": {\n    \"player.speed\": 650,\n    \"title\": \"Café ☕\"\n  }\n}\n";
        assert_eq!(hex(fnv1a64(SHARED_TEXT.as_bytes())), "f023d7fb6405f538");
    }

    #[test]
    fn hex_is_sixteen_lowercase_digits() {
        assert_eq!(hex(0xAB), "00000000000000ab");
    }

    #[test]
    fn table_is_sorted_and_skips_schema() {
        assert!(EMBEDDED.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(EMBEDDED.iter().all(|(p, _)| !p.starts_with("schema/")));
        assert!(
            EMBEDDED
                .iter()
                .all(|(p, _)| p.split('/').all(|part| !part.starts_with('.'))),
            "dotfiles are never content"
        );
    }
}
